SELECT 
FROM bt_data_table_column a
WHERE a.status_cd = '00A'
  AND a.table_column_id = #{tableColumnId}
  AND a.tenant_id = #{tenantId}

SELECT 
FROM bt_data_table_column a
WHERE a.status_cd = '00A'
  AND a.table_id = #{tableId}
  AND a.tenant_id = #{tenantId}
ORDER BY a.table_column_id

SELECT CASE WHEN COUNT(1) > 0 THEN 1 ELSE 0 END
FROM bt_data_table_column
WHERE status_cd = '00A'
  AND table_id = #{tableId}
  AND tenant_id = #{tenantId}
  AND column_code = #{columnCode}
